import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import test from 'node:test';
import { REPORT_DESIGN_TOKENS, buildPeriodicPdfFoundations } from '../src/reports/pdf-production.js';
import { GoogleDriveReadOnlyAdapter, approvePdfReview, createPdfHumanReviewPackage, createReportManifest, defaultDriveFolderRegistry, duplicateDecision, enhancedArticlePdfConsistency, publicAvailabilityGate, publicReportEntries } from '../src/reports/report-review-storage.js';
const artifact = JSON.parse(readFileSync('data/reports/review/daily/ai/artifact.json', 'utf8'));
const validation = JSON.parse(readFileSync('data/reports/review/daily/ai/validation.json', 'utf8'));
const review = () => createPdfHumanReviewPackage(artifact, validation, 'data/reports/review/daily/ai/contact-sheet.png');
test('Sprint 4J creates a complete PDF Human Review package in PENDING', () => { const item = review(); assert.equal(item.reviewState, 'PENDING'); assert.equal(item.reviewedBy, null); assert.equal(item.validationSummary.status, 'PASS'); assert.ok(Object.values(item.visualChecks).every(value => value === 'PENDING')); assert.ok(Object.values(item.contentChecks).every(value => value === 'PENDING')); });
test('Sprint 4J blocks automatic approval until every review check passes', () => { assert.throws(() => approvePdfReview(review(), 'human', '2026-10-02T10:00:00+09:00', null), /BLOCKED/); const item = review(); for (const key of Object.keys(item.visualChecks))
    item.visualChecks[key] = 'PASS'; for (const key of Object.keys(item.contentChecks))
    item.contentChecks[key] = 'PASS'; assert.equal(approvePdfReview(item, 'human', '2026-10-02T10:00:00+09:00', '검수 완료').reviewState, 'APPROVED'); });
test('Sprint 4J generates readable PNG contact sheets for all review artifacts', () => { for (const path of ['data/reports/review/daily/ai/contact-sheet.png', 'data/reports/review/daily/us/contact-sheet.png', 'data/reports/review/daily/korea/contact-sheet.png', 'data/reports/review/weekly/contact-sheet.png']) {
    assert.equal(existsSync(path), true);
    assert.deepEqual([...readFileSync(path).subarray(0, 8)], [137, 80, 78, 71, 13, 10, 26, 10]);
} });
test('Sprint 4J Weekly preview has explicit page-role sections and no unsupported trend blocks', () => { const weekly = buildPeriodicPdfFoundations().weekly; const titles = weekly.sections.map(section => section.title); assert.deepEqual(titles, ['Executive Summary', 'Week at a Glance', 'AI & Industry', 'U.S. Market', 'Korea Market', 'Cross Intelligence', 'Investment Map', 'Risks', 'Next Week Watch']); assert.equal(weekly.previewOnly, true); assert.doesNotMatch(titles.join(' '), /Consensus|Divergence|Trend Change/); });
test('Sprint 4J generated Weekly artifact is four-page validated preview', () => { const item = JSON.parse(readFileSync('data/reports/review/weekly/artifact.json', 'utf8')); const result = JSON.parse(readFileSync('data/reports/review/weekly/validation.json', 'utf8')); assert.equal(item.pageCount, 4); assert.equal(item.reviewState, 'PENDING'); assert.equal(result.status, 'PASS'); assert.equal(result.pageCount, 4); });
test('Sprint 4J uses one shared report design token master', () => { assert.equal(REPORT_DESIGN_TOKENS.MOTUS_NAVY, '#03162e'); assert.equal(REPORT_DESIGN_TOKENS.POSITIVE_RED, '#c62828'); assert.equal(REPORT_DESIGN_TOKENS.NEGATIVE_BLUE, '#1565c0'); assert.ok(REPORT_DESIGN_TOKENS.bodyMinimumPt >= 8); });
test('Sprint 4J Drive adapter reports NOT_CONFIGURED without credentials', async () => { const drive = new GoogleDriveReadOnlyAdapter({}); const status = await drive.status(); assert.equal(status.configured, 'NO'); assert.equal(status.credentialFingerprint, null); assert.equal(status.credentialValidation, 'NOT_CONFIGURED'); assert.equal(status.rootFolder, 'UNKNOWN'); });
test('Sprint 4J Drive writes and public shares remain disabled', async () => { const drive = new GoogleDriveReadOnlyAdapter({}); assert.equal(drive.writeEnabled, false); assert.equal(drive.publicShareEnabled, false); await assert.rejects(() => drive.uploadArtifact(artifact), /WRITE_DISABLED/); await assert.rejects(() => drive.createShareLink('file'), /PUBLIC_SHARE_DISABLED/); });
test('Sprint 4J Drive logs only a fingerprint for configured credential material', async () => { const drive = new GoogleDriveReadOnlyAdapter({ GOOGLE_DRIVE_CLIENT_ID: 'id', GOOGLE_DRIVE_CLIENT_SECRET: 'secret', GOOGLE_DRIVE_REFRESH_TOKEN: 'refresh' }); const status = await drive.status(); assert.equal(status.configured, 'YES'); assert.match(status.credentialFingerprint, /^[a-f0-9]{8}$/); assert.equal(status.credentialValidation, 'NOT_RUN'); assert.doesNotMatch(JSON.stringify(status), /secret|refresh/); });
test('Sprint 4J folder registry uses stable logical paths and no invented IDs', () => { const registry = defaultDriveFolderRegistry(); assert.equal(registry.length, 8); assert.equal(new Set(registry.map(item => item.logicalPath)).size, registry.length); assert.ok(registry.every(item => item.driveFolderId === null && item.state === 'UNVERIFIED')); });
test('Sprint 4J duplicate fingerprint is UNCHANGED', () => { assert.deepEqual(duplicateDecision([artifact], structuredClone(artifact)), { decision: 'UNCHANGED', nextVersion: 1 }); });
test('Sprint 4J changed fingerprint requires an immutable new version', () => { assert.deepEqual(duplicateDecision([artifact], { ...artifact, artifactId: 'new', contentFingerprint: 'changed' }), { decision: 'NEW_VERSION_REQUIRED', nextVersion: 2 }); });
test('Sprint 4J unrelated artifact starts at version one', () => { assert.deepEqual(duplicateDecision([], { ...artifact, artifactId: 'other' }), { decision: 'NEW_ARTIFACT', nextVersion: 1 }); });
test('Sprint 4J manifest keeps local review storage and public states separate', () => { const manifest = createReportManifest(artifact); assert.equal(manifest.validationState, 'VALIDATED'); assert.equal(manifest.reviewState, 'PENDING'); assert.equal(manifest.storageState, 'LOCAL_ONLY'); assert.equal(manifest.publicState, 'PRIVATE'); });
test('Sprint 4J public availability gate requires every distribution condition', () => { const manifest = { ...createReportManifest(artifact), reviewState: 'APPROVED', storageState: 'UPLOADED', publicState: 'PUBLIC_AVAILABLE' }; assert.equal(publicAvailabilityGate({ manifest, articleState: 'PUBLISHED', shareLinkValidated: true }), true); assert.equal(publicAvailabilityGate({ manifest: { ...manifest, reviewState: 'PENDING' }, articleState: 'PUBLISHED', shareLinkValidated: true }), false); assert.equal(publicAvailabilityGate({ manifest, articleState: 'DRAFT', shareLinkValidated: true }), false); });
test('Sprint 4J public Reports Archive hides private artifacts', () => { assert.deepEqual(publicReportEntries([{ title: 'private', issueDate: '2026-09-30', periodStart: '2026-09-30', periodEnd: '2026-09-30', category: 'US_MARKET', reportType: 'US_MARKET_DAILY', downloadUrl: null, articleUrl: null, generatedAt: '2026-10-02T00:00:00Z', publishedAt: null, state: 'PREVIEW_READY' }]), []); });
test('Sprint 4J enhanced article/PDF mismatch becomes HOLD', () => { const common = { issueDate: '2026-09-30', category: 'US_MARKET', headlineFingerprint: 'h', marketValuesFingerprint: 'm', sourceFingerprint: 's', chartSeriesFingerprint: 'c' }; assert.deepEqual(enhancedArticlePdfConsistency({ article: common, pdf: common }), { state: 'PASS', reason: null }); assert.deepEqual(enhancedArticlePdfConsistency({ article: common, pdf: { ...common, chartSeriesFingerprint: 'different' } }), { state: 'HOLD', reason: 'CONTENT_MISMATCH' }); });
test('Sprint 4J Monthly remains HOLD and has no review PDF', () => { assert.equal(buildPeriodicPdfFoundations().monthly.previewOnly, true); assert.equal(existsSync('data/reports/review/monthly/report.pdf'), false); });
test('Sprint 4J report artifacts contain no Commerce or advertising block', () => { const manifest = readFileSync('data/reports/review/report-manifest.json', 'utf8'); assert.match(manifest, /"enabled": false/); assert.doesNotMatch(manifest, /affiliate|advertising|ad block/i); });
